
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_xc_b97_gga1_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_xc_b97_gga1", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.565894327626629e+00, -4.472510412446595e+00, -4.341728313740147e+00, -4.160723899898118e+00, -3.914464227865007e+00, -3.587676859698934e+00, -3.169730615565475e+00, -2.664670500250049e+00, -2.109666892347105e+00, -1.593193467263384e+00, -1.137700402483493e+00, -7.755679162306640e-01, -6.676183131373556e-01, -5.424841901777635e-01, -3.869368487050882e-01, -2.483801589489527e-01, -1.915125805145045e-01, -1.070973530304083e-01, -2.696996113458238e-02, -3.217404406866903e-03]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


